        </svg>
      </button>
      {isOpen && (
        <div className="details">
          {answer}
        </div>
      )}
    </div>
  );
};

const App = () => {
  const faqs = [
    {
      question: "Why do cats purr?",
      answer: "Cats often purr when they are happy and content, but they also purr to soothe themselves when they are stressed or in pain. It's a versatile form of communication!"
    },
    {
      question: "Why do cats have whiskers?",
      answer: "Whiskers are highly sensitive tactile organs. They help cats navigate in the dark, judge the width of openings, and detect changes in air currents."
    },
    {
      question: "Why do cats sleep so much?",
      answer: "Cats are crepuscular predators, meaning they are most active at dawn and dusk. They sleep an average of 12-16 hours a day to conserve energy for hunting."
    },
    {
      question: "How do cats always land on their feet?",
      answer: "Cats have a 'righting reflex' thanks to their flexible spine and lack of a collarbone. This allows them to quickly twist their bodies in mid-air during a fall."
    },
    {
      question: "Why do cats knead?",
      answer: "Kneading (or 'making biscuits') is a behavior carried over from kittenhood, where kittens knead their mothers to stimulate milk flow. In adults, it's a sign of comfort and affection."
